        raise ValueError(
            "request keys must be exactly and in order: "
            "key, users, base, left, right"
        )
    key = doc["key"]
    users = doc["users"]
    base = doc["base"]
    left = doc["left"]
    right = doc["right"]
    for name, value in (
        ("key", key), ("base", base), ("left", left), ("right", right),
